//
// Стенд проверки геометрии. Строит геометрию сцены без запуска физики и сверяет
// её с тем, что ожидает генератор (generated/ExpectedChecks.hh):
//   1. перекрытия объёмов (G4VPhysicalVolume::CheckOverlaps, выборочно по точкам);
//   2. объём каждого тела в Geant4 против cad_volume из FreeCAD;
//   3. пробные точки: в каждой должно найтись нужное тело с нужным материалом —
//      это и есть проверка поворотов и положения.
// Код возврата: 0 — всё сошлось, 1 — есть проблемы.
//
// Запуск: ./check_geometry [число точек CheckOverlaps на объём, по умолчанию 100000]

#include <cmath>
#include <cstdlib>
#include <string>

#include "G4GeometryManager.hh"
#include "G4LogicalVolume.hh"
#include "G4LogicalVolumeStore.hh"
#include "G4Material.hh"
#include "G4Navigator.hh"
#include "G4PhysicalVolumeStore.hh"
#include "G4SystemOfUnits.hh"
#include "G4VPhysicalVolume.hh"
#include "G4VSolid.hh"
#include "G4ios.hh"

#include "ExpectedChecks.hh"
#include "GeneratedDetectorConstruction.hh"

int main(int argc, char** argv) {
  const int overlapPoints = argc > 1 ? std::atoi(argv[1]) : 100000;

  G4cout << "check_geometry: сцена " << expected::kSceneName << G4endl;
  GeneratedDetectorConstruction construction;
  G4VPhysicalVolume* world = construction.Construct();
  int problems = 0;

  // 1. Перекрытия. Проверка выборочная: «OK» значит, что из overlapPoints
  //    случайных точек на поверхности ни одна не попала в соседа или за мать.
  G4cout << "\n== 1. Перекрытия (CheckOverlaps, " << overlapPoints << " точек на объём)" << G4endl;
  for (G4VPhysicalVolume* pv : *G4PhysicalVolumeStore::GetInstance()) {
    if (pv == world) continue;
    if (pv->CheckOverlaps(overlapPoints, 0., true, 1)) ++problems;
  }

  // 2. Объёмы.
  G4cout << "\n== 2. Объёмы тел (Geant4 против cad_volume)" << G4endl;
  for (const auto& e : expected::kVolumes) {
    G4LogicalVolume* lv = G4LogicalVolumeStore::GetInstance()->GetVolume(e.name, false);
    if (lv == nullptr) {
      G4cout << "  НЕТ    " << e.name << ": такого объёма в геометрии нет" << G4endl;
      ++problems;
      continue;
    }
    const double g4 = lv->GetSolid()->GetCubicVolume() / mm3;
    const double rel = std::abs(g4 - e.cadVolume) / e.cadVolume;
    const bool ok = rel <= e.relTol;
    G4cout << "  " << (ok ? "OK     " : "ОШИБКА ") << e.name << ": Geant4 " << g4
           << " мм3, CAD " << e.cadVolume << " мм3, расхождение " << rel
           << " (допуск " << e.relTol << ")" << G4endl;
    if (!ok) ++problems;
  }

  // 3. Пробные точки.
  G4cout << "\n== 3. Пробные точки (" << expected::kProbes.size() << ")" << G4endl;
  G4GeometryManager::GetInstance()->CloseGeometry();
  G4Navigator navigator;
  navigator.SetWorldVolume(world);
  int probesBad = 0;
  for (const auto& p : expected::kProbes) {
    const G4ThreeVector pos(p.x * mm, p.y * mm, p.z * mm);
    G4VPhysicalVolume* pv = navigator.LocateGlobalPointAndSetup(pos, nullptr, false, true);
    const std::string vol = pv ? std::string(pv->GetName()) : std::string("<снаружи мира>");
    const std::string mat =
        pv ? std::string(pv->GetLogicalVolume()->GetMaterial()->GetName()) : std::string("-");
    if (vol != p.volume || mat != p.material) {
      G4cout << "  ОШИБКА (" << p.x << ", " << p.y << ", " << p.z << ") мм: найдено " << vol
             << " / " << mat << ", ожидалось " << p.volume << " / " << p.material << G4endl;
      ++probesBad;
    }
  }
  if (probesBad == 0) G4cout << "  OK: все точки попали в свои тела" << G4endl;
  problems += probesBad;

  G4cout << "\n" << (problems == 0 ? "OK" : "FAILED") << ": " << problems << " problems" << G4endl;
  return problems == 0 ? 0 : 1;
}
